import{b as a,O as s,g as n,j as i}from"./chunks/framework.DcaUmd3X.js";const h=JSON.parse('{"title":"Git简介","description":"","frontmatter":{},"headers":[],"relativePath":"git/intro/git-intro/index.md","filePath":"Git操作手册/1.起步/01.Git简介.md","lastUpdated":1782199931000}'),o={name:"git/intro/git-intro/index.md"};function e(l,t,r,p,d,c){return s(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="git简介" tabindex="-1">Git简介 <a class="header-anchor" href="#git简介" aria-label="Permalink to &quot;Git简介&quot;">​</a></h1><blockquote><p>什么是版本控制？Git 是什么？为什么要学它？</p></blockquote><h2 id="没有版本控制的日子" tabindex="-1">没有版本控制的日子 <a class="header-anchor" href="#没有版本控制的日子" aria-label="Permalink to &quot;没有版本控制的日子&quot;">​</a></h2><p>想象一个场景：你在写一个项目，文件夹里是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>项目v1.doc</span></span>
<span class="line"><span>项目v1-修改版.doc</span></span>
<span class="line"><span>项目v2-最终版.doc</span></span>
<span class="line"><span>项目v2-最终版-真的最终.doc</span></span>
<span class="line"><span>项目v2-最终版-打死不改.doc</span></span></code></pre></div><p>是不是很眼熟？这就是<strong>手动版本管理</strong>——靠文件名区分版本。</p><p>问题很快就来了：改乱了想回到三天前的版本，找不到了。同事改了同一个文件发给你，你不知道哪些是他改的、哪些是你改的。项目出了 bug，不知道是谁、什么时候、改了什么引入的。</p><p><strong>版本控制系统就是来解决这些问题的。</strong></p><h2 id="什么是版本控制" tabindex="-1">什么是版本控制 <a class="header-anchor" href="#什么是版本控制" aria-label="Permalink to &quot;什么是版本控制&quot;">​</a></h2><p>一句话：<strong>版本控制系统会记录文件的每次修改，让你随时可以回到任意历史版本。</strong></p><p>它做的事就是三件：</p><ol><li><strong>记录变更</strong> — 谁、什么时间、改了哪些行，一清二楚</li><li><strong>自由回退</strong> — 改错了？一秒回到任意历史版本</li><li><strong>多人协作</strong> — 两个人同时改一个文件不再互相覆盖</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>没有版本控制：                      有版本控制：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>你改 → 保存                       你改 → 提交 v1</span></span>
<span class="line"><span>同事改 → 覆盖你的 ❌               同事改 → 提交 v2</span></span>
<span class="line"><span></span></span>
<span class="line"><span>              想看 v1？一秒切回去 ✅</span></span></code></pre></div><h2 id="git-是什么" tabindex="-1">Git 是什么 <a class="header-anchor" href="#git-是什么" aria-label="Permalink to &quot;Git 是什么&quot;">​</a></h2><p>Git 是目前世界上最流行的<strong>分布式版本控制系统</strong>。2005 年，Linus Torvalds（对，就是 Linux 之父）用两周时间写出了 Git 的第一个版本，用来管理 Linux 内核的源代码。</p><p>为什么叫 Git？Linus 自嘲说是&quot;英国俚语里的蠢货&quot;，但也有人说它是 <strong>G</strong>lobal <strong>I</strong>nformation <strong>T</strong>racker 的缩写。</p><p>到今天，Git 已经成了开发者的标配技能——GitHub、GitLab、Gitee 这些代码托管平台，底层全是 Git。</p><h2 id="集中式-vs-分布式" tabindex="-1">集中式 vs 分布式 <a class="header-anchor" href="#集中式-vs-分布式" aria-label="Permalink to &quot;集中式 vs 分布式&quot;">​</a></h2><p>版本控制系统分两派：</p><table tabindex="0"><thead><tr><th></th><th>集中式（SVN）</th><th>分布式（Git）</th></tr></thead><tbody><tr><td>代码存在哪</td><td>只有中央服务器</td><td>每人电脑上都有完整仓库</td></tr><tr><td>没网能干活吗</td><td>❌ 不能 commit</td><td>✅ 随便 commit，有网再推</td></tr><tr><td>服务器挂了</td><td>❌ 所有人都没法干活</td><td>✅ 每人本地都有完整备份</td></tr><tr><td>分支操作</td><td>慢、重</td><td>秒切、轻量</td></tr></tbody></table><p><strong>Git 的核心优势就是&quot;去中心化&quot;</strong>——你的电脑上存着完整的仓库历史，不依赖网络，不依赖服务器。这也是为什么 Git 分支切得飞快、回退秒完成。</p><h2 id="git-能做什么" tabindex="-1">Git 能做什么 <a class="header-anchor" href="#git-能做什么" aria-label="Permalink to &quot;Git 能做什么&quot;">​</a></h2><p>不只是存代码。日常你会用它做这些事：</p><ul><li><strong>保存进度</strong> — 写了一个功能，commit 一下留个快照</li><li><strong>回到过去</strong> — 三天前引入的 bug？回退到那个版本对比排查</li><li><strong>并行开发</strong> — 开个分支做新功能，主分支不受影响</li><li><strong>合并成果</strong> — 功能写完了，合并回主分支</li><li><strong>追溯责任</strong> — 这行 bug 谁写的？<code>git blame</code> 一秒定位</li><li><strong>团队协作</strong> — 多人同时改项目，互不覆盖</li></ul><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这章记住三件事：</p><ol><li><strong>版本控制 = 时光机</strong> — 记录了每次修改，随时回到任意版本</li><li><strong>Git 是分布式的</strong> — 每人电脑上都有完整仓库，不依赖服务器</li><li><strong>Git 不仅是存代码</strong> — 回退、分支、追溯、协作，日常开发全流程都在上面</li></ol><blockquote><p>💡 下一章把 Git 装到电脑上，开始你的第一次版本控制。</p></blockquote><h2 id="自主练习" tabindex="-1">自主练习 <a class="header-anchor" href="#自主练习" aria-label="Permalink to &quot;自主练习&quot;">​</a></h2><ol><li>你遇到过哪些&quot;手动管理版本&quot;的痛点？想一想版本控制能解决哪些</li><li>用自己的话解释集中式和分布式的区别（讲给同事听，看能不能讲明白）</li><li>Git 是谁在什么时候创造的？为什么叫这个名字？</li></ol>`,30)])])}const u=a(o,[["render",e]]);export{h as __pageData,u as default};
